66	#let twyne-initial-parts(body) = {
67	  if body.func() == smartquote or body.func() == metadata or ("space", "tag").contains(repr(body.func())) {
68	    (initial: none, prefix: body, rest: [], skip: true)
69	  } else if body.func() == text and body.has("text") {
70	    let letters = body.text.clusters()
71	    let offset = 0
72	    while offset < letters.len() and (letters.at(offset).trim() == "" or ("“", "‘", "\\"", "'", "«", "‹", "「", "『", "(", "[", "{", "¿", "¡").contains(letters.at(offset))) { offset += 1 }
