76	  } else if body.has("children") and body.children.len() > 0 {
77	    let prefix = []
78	    for (index, child) in body.children.enumerate() {
79	      let first = twyne-initial-parts(child)
80	      if first.initial != none { return (initial: first.initial, prefix: prefix + first.prefix, rest: first.rest + body.children.slice(index + 1).join(), skip: false) }
