86	    let first = twyne-initial-parts(body.child)
87	    (initial: first.initial, prefix: body.func()(first.prefix, body.styles), rest: body.func()(first.rest, body.styles), skip: first.skip)
88	  } else if (strong, emph, underline, strike, super, sub, link).contains(body.func()) {
89	    let first = twyne-initial-parts(body.body)
90	    let fields = body.fields()
91	    let discarded = fields.remove("body")
92	    let wrap(content) = if body.func() == link { link(fields.dest, content) } else { body.func()(content, ..fields) }
93	    (initial: first.initial, prefix: wrap(first.prefix), rest: wrap(first.rest), skip: first.skip)
