96	// Keep rich inline styling while finding word boundaries for the side of the
97	// drop cap. Adjacent marked fragments of one word must stay together.
98	#let twyne-opening-tokens(body) = {
99	  if body.func() == text and body.has("text") {
100	    body.text.matches(regex("\\\\s+|[^\\\\s]+")).map(part => (
101	      body: text(part.text), space: part.text.trim() == "",
