118	  show par: it => it
119	  let cap = measure(initial)
120	  let gap = 0.14 * twyne-initial-size
121	  let width = bounds.width - cap.width - gap
122	  // Very narrow columns still retain all manuscript content.
123	  if width < (2em).to-absolute() { return initial + h(gap) + body }
