127	  let join(start, end) = tokens.slice(start, end).map(token => token.body).join()
128	  // Measure with the active font, paragraph leading and actual column width.
129	  // Binary search bounds the work even for a long opening paragraph.
130	  let low = 0
131	  let high = breaks.len()
132	  while low < high {
133	    let middle = calc.floor((low + high) / 2)
134	    let height = measure(block(width: width, above: 0pt, below: 0pt, twyne-opening-line(join(0, breaks.at(middle))))).height
