136	  }
137	  let end = if low == 0 { breaks.first() } else { breaks.at(low - 1) }
138	  let next = end
139	  while next < tokens.len() and tokens.at(next).space { next += 1 }
140	  let beside = join(0, end)
141	  let below = join(next, tokens.len())
142	  block(width: 100%, above: 0pt, below: 0pt, grid(
143	    columns: (cap.width, 1fr), column-gutter: gap,
144	    initial,
145	    twyne-opening-line([#beside#if next < tokens.len() { linebreak(justify: par.justify) }]),
146	  ))
147	  if next < tokens.len() {
148	    v(par.leading, weak: true)
